def test_oserror_on_change_write_propagates_and_keeps_state(self):
    s = self.build()
    real_fsync = os.fsync
    calls = {"n": 0}

    def flaky(fd):
        calls["n"] += 1
        if calls["n"] == 4:  # first restore change record (a set)
            raise OSError("disk on fire")
        return real_fsync(fd)

    with mock.patch("app.os.fsync", side_effect=flaky):
        with self.assertRaises(OSError):
            s.restore(1)
    # old committed state/seq unchanged
    self.assertEqual(s.commit_seq, 3)
    self.assertEqual(s.state, {"b": {"n": [1]}, "c": 3, "d": True})
    # a reopen sees the same committed state; failed record is not pending
    # (_append truncated its own failed record back), seq chain intact
    s2 = WalStore(self.path)
    self.assertEqual((s2.state, s2.commit_seq),
                     ({"b": {"n": [1]}, "c": 3, "d": True}, 3))
    # retry succeeds with the next seq
    self.assertEqual(s2.restore(1), 4)
    self.assertEqual(s2.state, {"a": 1, "b": {"n": [1]}})

def test_oserror_mid_batch_leaves_pending_for_rollback(self):
    # Simulate failure on a write() (not fsync) after an earlier change
    # record already became durable: surviving records stay pending.
    s = self.build()
    real_open = Path.open

    real_write = None
    state = {"opened": 0}

    class Flaky:
        def __init__(self, f):
            self.f = f

        def __enter__(self):
            self.f.__enter__()
            return self

        def __exit__(self, *a):
            return self.f.__exit__(*a)

        def write(self, data):
            state["opened"] += 1
            if state["opened"] == 2:  # second change record (delete c)
                raise OSError("write failed")
            return self.f.write(data)

        def flush(self):
            return self.f.flush()

        def tell(self):
            return self.f.tell()

        def truncate(self, *a, **k):
            return self.f.truncate(*a, **k)

    def patch_open(self_path, mode="r", *args, **kwargs):
        f = real_open(self_path, mode, *args, **kwargs)
        if "a" in mode and state["opened"] >= 1:
            # wrap only the second append's file object
            if state["opened"] == 1:
                return Flaky(f)
        return f

    # simpler deterministic approach: fail fsync on the 2nd restore
    # record; the 1st record is durable and remains pending after the
    # failed call.
    real_fsync = os.fsync
    n = {"i": 0}

    def flaky(fd):
        n["i"] += 1
        if n["i"] == 5:  # seq-4 batch: records are set a (4), del c (5)
            raise OSError("disk on fire")
        return real_fsync(fd)

    with mock.patch("app.os.fsync", side_effect=flaky):
        with self.assertRaises(OSError):
            s.restore(1)
    self.assertEqual(s.commit_seq, 3)
    self.assertEqual(s.state, {"b": {"n": [1]}, "c": 3, "d": True})
    # the one durable change record is pending and rollback clears it
    pc = s.pending_changes()
    self.assertEqual(pc.pending_count, 1)
    self.assertEqual(pc.changes, [{"op": "set", "key": "a", "value": 1}])
    self.assertEqual(s.rollback(), 1)
    self.assertEqual(s.pending_changes().pending_count, 0)
    self.assertEqual((s.state, s.commit_seq),
                     ({"b": {"n": [1]}, "c": 3, "d": True}, 3))
    # and the restore can run cleanly afterwards
    self.assertEqual(s.restore(1), 4)

